<template>
  <div v-show="is_show" class="userInfo mb-10 mb-sm-5">
    <h3 class="text-medium py-4 px-5 mb-10 mb-sm-5 mt-sm-5">訂購資料</h3>
    <FormView v-slot="{ errors }" @submit="onSubmit" class="px-5 px-md-0">
      <div class="row">
        <div class="col-lg-6">
          <div class="form-control mb-2">
            <label for="name" class="mb-1">
              訂購人
              <ErrorMessage name="name" class="invalid-feedback"></ErrorMessage>
            </label>
            <FieldView
              id="name"
              name="name"
              type="text"
              class="form-input"
              :class="{ 'is-invalid': errors['name'] }"
              placeholder="請輸入 姓名"
              rules="required"
              v-model="form.user.name"
            ></FieldView>
          </div>
          <div class="form-control mb-2">
            <label for="region" class="mb-1">
              地區選擇
              <ErrorMessage
                name="address"
                class="invalid-feedback"
              ></ErrorMessage>
            </label>
            <FieldView
              id="address"
              name="address"
              :class="{ 'is-invalid': errors['address'] }"
              placeholder="請輸入地區"
              rules="required"
              as="select"
              v-model="form.user.address"
            >
              <option value="">請選擇地區</option>
              <option value="信義區">信義區</option>
              <option value="信義區">大安區</option>
            </FieldView>
          </div>
          <div class="form-control mb-2">
            <label for="region" class="mb-1">
              地址
              <ErrorMessage
                name="address_str"
                class="invalid-feedback"
              ></ErrorMessage>
            </label>
            <FieldView
              id="address_str"
              name="address_str"
              :class="{ 'is-invalid': errors['address_str'] }"
              placeholder="請輸入地址"
              rules="required"
              as="input"
              v-model="form.user.address_str"
            ></FieldView>
          </div>
          <div class="form-control mb-2">
            <label for="phone" class="mb-1">
              電話
              <ErrorMessage name="電話" class="invalid-feedback"></ErrorMessage>
            </label>
            <FieldView
              id="phone"
              name="電話"
              type="text"
              :class="{ 'is-invalid': errors['電話'] }"
              placeholder="請輸入電話"
              :rules="isPhone"
              v-model="form.user.tel"
            ></FieldView>
          </div>
          <div class="form-control mb-2">
            <label for="message" class="mb-1">留言</label>
            <FieldView
              id="message"
              name="message"
              type="text"
              v-model="form.message"
              as="textarea"
            ></FieldView>
          </div>
        </div>
        <div class="col-lg-6 mt-7 mb-sm-7">
          <div class="row">
            <div class="col-sm-6">
              <div
                class="pay_credit"
                :class="{ active: is_credit == true }"
                @click="is_credit = true"
              >
                <span>轉帳付款</span>
                <span class="icon">
                  <CreditCardIcon></CreditCardIcon>
                </span>
              </div>
            </div>
            <div class="col-sm-6">
              <div
                class="pay_cash"
                :class="{ active: is_credit == false }"
                @click="is_credit = false"
              >
                <span>現金付款</span>
                <span class="icon">
                  <CashIcon></CashIcon>
                </span>
              </div>
            </div>
            <div class="col-lg-12 d-sm-none">
              <button
                class="user-btn user-btn-primary w-100 py-4 mb-0 mt-auto f-size-xs"
                type="submit"
              >
                下一步：完成付款
              </button>
            </div>
          </div>
        </div>
      </div>
      <button
        class="cart-check-btn user-btn user-btn-primary w-100 py-3 f-size-xs"
        type="submit"
      >下一步：完成付款</button>
    </FormView>
  </div>
</template>

<script>
import { CreditCardIcon, CashIcon } from '@heroicons/vue/outline'
export default {
  props: ['show'],
  data () {
    return {
      is_credit: false,
      is_show: false,
      form: {
        user: {}
      }
    }
  },
  components: {
    CreditCardIcon,
    CashIcon
  },
  methods: {
    onSubmit () {
      this.$emitter.emit('isLoading', true)
      const order = this.form
      order.is_cash = !this.is_credit
      order.card_id = localStorage.getItem('cart_id')
      this.$http
        .post(`${process.env.VUE_APP_APIURL}/api/${process.env.VUE_APP_PATH}/order`, { data: order })
        .then((res) => {
          localStorage.removeItem('cart_id')
          console.log('in res')
          this.initializeCartId()
          this.$emitter.emit('isLoading', false)
          console.log('in updateCart emmiter')
          console.log(this.$emitter)
          this.$emitter.emit('update_cart', { carts: [] })
          console.log('in updateCart emmiter over')
          this.$router.push({ name: '完成結帳頁面', params: { show_complete: true, id: res.data.orderId } })
        })
        .catch((err) => {
          this.$emitter.emit('isLoading', false)
          this.$httpMessageState(err.response, '結帳')
        })
    },
    payOrder (orderId) {
      this.$http
        .post(`${process.env.VUE_APP_APIURL}/api/${process.env.VUE_APP_PATH}/pay/${orderId}`)
        .then(() => {
          this.$emitter.emit('isLoading', false)
          this.$emitter.emit('update_cart', { carts: [] })
          this.$router.push({ name: '完成結帳頁面', params: { show_complete: true, id: orderId } })
        })
        .catch((err) => {
          this.$emitter.emit('isLoading', false)
          this.$httpMessageState(err.response, '信用卡付款')
        })
    },
    isPhone (value) {
      const phoneNumber = /^(09)[0-9]{8}$/
      return phoneNumber.test(value) ? true : '需要正確的電話號碼'
    },
    generateCartId () {
      // 生成 16 位元隨機字串
      const characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789'
      let result = ''
      for (let i = 0; i < 16; i++) {
        result += characters.charAt(Math.floor(Math.random() * characters.length))
      }
      return result
    },
    initializeCartId () {
      if (!localStorage.getItem('cart_id')) {
        const cartId = this.generateCartId()
        localStorage.setItem('cart_id', cartId)
        console.log(`Generated cart_id: ${cartId}`)
      } else {
        console.log(`Existing cart_id: ${localStorage.getItem('cart_id')}`)
      }
    }
  },
  mounted () {
    if (this.show) {
      this.is_show = true
      this.$emitter.emit('changeBar', 2)
    } else {
      this.$router.push('/cart')
    }
  }
}
</script>

